function parseCsvRow(row){if(/[\r\n]/.test(row))throw Error();let out=[],i=0;while(true){let v='';if(row[i]==='"'){i++;let closed=false;while(i<row.length){if(row[i]==='"'){if(row[i+1]==='"'){v+='"';i+=2;}else{i++;closed=true;break;}}else v+=row[i++];}if(!closed||(i<row.length&&row[i]!==','))throw Error();}else{while(i<row.length&&row[i]!==','){if(row[i]==='"')throw Error();v+=row[i++];}}out.push(v);if(i===row.length)return out;i++;}}module.exports=parseCsvRow;
